NEW_FILES = {'zoo_keeper/genome/species/pew.json': '{\n  "species": "pew",\n  "version": 1,\n  "license": {\n    "construction_knowledge": "CC0",\n    "notes": "Minted 2026-10-25 by tools/new_species.py; shaped the same day for the factory\'s roadmap 308 (a chapel, a viewing room, a courtroom\'s public benches, an assembly room). REFERENCE: an American oak pew, the common catalogue pattern -- two end panels the full height and depth, a seat 0.45 m up meeting a back behind it, a hymnal rack on the back\'s rear for the row behind and, in a deep slot, a kneeler for that row; one stained wood throughout. The range reaches the 8.0 x 0.9 m `pew_row` boxes Deli Counter\'s funeral_home_a01 chapel authored."\n  },\n  "dimensions": {\n    "width": {\n      "min": 1.2,\n      "max": 8.0,\n      "default": 3.6\n    },\n    "depth": {\n      "min": 0.5,\n      "max": 1.0,\n      "default": 0.62\n    },\n    "height": {\n      "min": 0.85,\n      "max": 1.1,\n      "default": 0.95\n    }\n  },\n  "parts": [\n    "Pew_End_L",\n    "Pew_End_R",\n    "Pew_Seat",\n    "Pew_Back",\n    "Pew_TopRail",\n    "Pew_Rack",\n    "Pew_Kneeler"\n  ],\n  "params": {},\n  "materials": {\n    "default": "wood",\n    "options": [\n      "concrete",\n      "metal",\n      "wood",\n      "plaster"\n    ]\n  },\n  "styles": {\n    "default": {\n      "material": "wood",\n      "color": [\n        0.42,\n        0.27,\n        0.15\n      ],\n      "wear": 0.15,\n      "bevel": 0.006\n    },\n    "delco": {\n      "material": "wood",\n      "color": [\n        0.36,\n        0.22,\n        0.12\n      ],\n      "wear": 0.35,\n      "bevel": 0.006,\n      "ambient": 0.35\n    },\n    "center_city": {\n      "material": "wood",\n      "color": [\n        0.4,\n        0.26,\n        0.15\n      ],\n      "wear": 0.122,\n      "bevel": 0.006,\n      "ambient": 0.15\n    },\n    "industrial_flats": {\n      "material": "wood",\n      "color": [\n        0.33,\n        0.21,\n        0.13\n      ],\n      "wear": 0.57,\n      "bevel": 0.006,\n      "ambient": 0.45\n    },\n    "rockay": {\n      "material": "wood",\n      "color": [\n        0.38,\n        0.24,\n        0.14\n      ],\n      "wear": 0.29,\n      "bevel": 0.006,\n      "ambient": 0.05\n    }\n  },\n  "budgets": {\n    "tris_lod0": 360\n  },\n  "attachments": [],\n  "collision": true,\n  "match_priority": 0,\n  "keywords": [\n    "pew",\n    "church_pew",\n    "gallery_pew"\n  ]\n}\n', 'zoo_keeper/recipes/pew.py': '"""pew recipe: a church pew -- two solid ends, a seat, a high back and a book rack.\n\nThe factory\'s roadmap 308: a chapel, a funeral home\'s viewing room, a\ncourtroom\'s public benches and an assembly room were furnished as a\ncafeteria, because Deli Counter had no seat for a row that faces one front\nand Zoo\'s `bench` is a street bench with no back. REFERENCE: an American\noak pew, the common pattern of church-furniture catalogues -- two end\npanels the pew\'s full height and depth, a seat 0.45 m up and about 0.46 m\ndeep meeting a back behind it, a rack on the back\'s rear for the hymnals of\nthe row behind and, where the slot is deep enough, a kneeler for that row at\nthe floor. Every part is the same stained wood, one material, so a room of\npews is one mesh a row to the merge.\n\nTHE SEAT IS A PEW\'S DEPTH WHATEVER THE SLOT\'S. A slot deeper than a seat,\nback and rack -- the 0.9 m `pew_row` boxes Deli Counter\'s funeral home\nauthored -- keeps the seat at `SEAT_D` and puts the rest behind the rack as\nthe kneeler, rather than stretching the seat until nobody\'s knees reach its\nedge; a first draft ran the seat to a back pushed against the slot\'s rear.\n\nRecipe frame: centre pivot, the FRONT (where a person sits facing) at -y,\nthe back at +y, as `chair.py`\'s. The two ends are the pew\'s whole extent\nin every axis, so the module is exactly (w, d, h) whatever the parts\ninside them do. Collision is the pew as one block: a body walks the aisle,\nnever through a row.\n\nNO TWO FACES SHARE A PLANE (`tests/test_coincident_faces.py`): every part\nruns `BURY` into whatever it meets -- the seat, back, rail and rack into\nboth ends, the back into the seat and the rail, the shelf into the back and\nthe lip -- and stops `FACE_GAP` short of the ends\' outer faces, so a face\nthat meets another is inside it rather than on it. Parts that pass into one\nanother also end at different depths in the ends -- the back and the rack\'s\nlip half as deep as the seat, rail and shelf -- or their end faces would\nshare a plane inside the end panel (the census\'s first reading: four pairs a\ncorner, Pew_Back with Pew_Seat and with Pew_Rack, all at x = +-span / 2).\n"""\nfrom __future__ import annotations\n\nfrom ..bpylayer import geometry, materials\n\nEND_T = 0.05          # an end panel\'s thickness along the pew\nSEAT_Z = 0.45         # the seat\'s top above the floor\nSEAT_T = 0.04\nBACK_T = 0.03\nTOP_RAIL = (0.05, 0.05)   # the back\'s cap, deep x tall\nRACK_D = 0.09         # the book rack, out from the back\'s rear face\nRACK_Z = 0.62         # the rack shelf\'s top above the floor\nRACK_T = 0.02\nRACK_LIP = 0.07       # the rack\'s lip, tall\nSEAT_D = 0.46         # front edge to the back\'s front face\nKNEEL = (0.18, 0.10, 0.10)   # the kneeler: deep, thick, its top\'s height above its underside\'s\nKNEEL_MIN = 0.25     # the depth left behind the rack that takes one\nBURY = 0.01\nFACE_GAP = 0.005\n\n\ndef build(plan, streams, collection):\n    w = plan["dimensions"]["width"]\n    d = plan["dimensions"]["depth"]\n    h = plan["dimensions"]["height"]\n    bevel, wear = plan["bevel"], plan["wear"]\n    rng = streams.stream("wear")\n    objs, cboxes = [], []\n    z0, y0, y1 = -h / 2.0, -d / 2.0, d / 2.0\n\n    def part(name, boxes):\n        bm = geometry.new_bm()\n        for centre, size in boxes:\n            geometry.add_box(bm, centre, size)\n        objs.append(geometry.bm_to_object(\n            bm, name, collection, bevel=bevel, texel=1.2, rng=rng, wear=wear))\n\n    # the two ends: the whole height and depth\n    for tag, sx in (("L", -1), ("R", 1)):\n        part(f"Pew_End_{tag}", [((sx * (w / 2.0 - END_T / 2.0), 0.0, 0.0), (END_T, d, h))])\n    span = w - 2.0 * END_T + 2.0 * BURY          # between the ends, into both\n    half = span - BURY                            # the back\'s and the lip\'s\n    # the back stands a seat\'s depth behind the front, or as far back as\n    # leaves the rack room; the rack hangs on the back\n    back_y = min(y1 - FACE_GAP - RACK_D - BACK_T / 2.0, y0 + FACE_GAP + SEAT_D + BACK_T / 2.0)\n    seat_z = z0 + min(SEAT_Z, h * 0.6)\n    seat_front = y0 + FACE_GAP\n    seat_back = back_y          # the seat runs into the back: no gap a hand falls through\n    part("Pew_Seat", [((0.0, (seat_front + seat_back) / 2.0, seat_z - SEAT_T / 2.0),\n                       (span, seat_back - seat_front, SEAT_T))])\n    rail_top = h / 2.0 - FACE_GAP\n    rail_lo = rail_top - TOP_RAIL[1]\n    back_lo = seat_z - SEAT_T / 2.0                      # into the seat\n    back_hi = rail_lo + BURY                              # into the rail\n    part("Pew_Back", [((0.0, back_y, (back_lo + back_hi) / 2.0), (half, BACK_T, back_hi - back_lo))])\n    part("Pew_TopRail", [((0.0, back_y, (rail_lo + rail_top) / 2.0), (span, TOP_RAIL[0], TOP_RAIL[1]))])\n    # the book rack for the row behind: a shelf from inside the back to inside\n    # the lip, and the lip hanging below the shelf\n    rack_top = min(z0 + RACK_Z, rail_lo - RACK_LIP)\n    lip_y = back_y + BACK_T / 2.0 + RACK_D - RACK_T / 2.0\n    shelf_y0, shelf_y1 = back_y, lip_y\n    part("Pew_Rack", [\n        ((0.0, (shelf_y0 + shelf_y1) / 2.0, rack_top - RACK_T / 2.0), (span, shelf_y1 - shelf_y0, RACK_T)),\n        ((0.0, lip_y, rack_top - 2.0 * RACK_T + RACK_LIP / 2.0), (half, RACK_T, RACK_LIP)),\n    ])\n    # the kneeler for the row behind, at the slot\'s rear, raised off the floor\n    if y1 - FACE_GAP - (lip_y + RACK_T / 2.0) >= KNEEL_MIN:\n        kd, kt, kz = KNEEL\n        part("Pew_Kneeler", [((0.0, y1 - FACE_GAP - kd / 2.0, z0 + kz + kt / 2.0), (span, kd, kt))])\n\n    cboxes.append(((-w / 2.0, -d / 2.0, -h / 2.0), (w / 2.0, d / 2.0, h / 2.0)))\n    wood = materials.make_material(\n        f"M_Pew_{plan[\'material\']}", plan["color"], plan["material"])\n    materials.assign(objs, wood)\n    return {"objects": objs, "collision_boxes": cboxes,\n            "attachments": {"ATT_seat_center": (0.0, (seat_front + seat_back) / 2.0, seat_z)}}\n', 'tests/test_pew.py': '"""pew: minted 2026-10-25 by tools/new_species.py (roadmap 150), shaped for the factory\'s roadmap 308 (a chapel, a\nviewing room, a courtroom\'s public benches and an assembly room furnished as a cafeteria, for want of a seat that faces\none front). The pure half plans it; the bpy half builds it. FAILS ON 1.129.0, which has no pew. Run inside Blender for\nthe shape:\n\n    blender -b --factory-startup --python-expr "import sys, pytest; sys.path.insert(0, \'.\'); print(\'rc\', int(pytest.main([\'-q\', \'-p\', \'no:cacheprovider\', \'tests/test_pew.py\'])))"\n"""\nimport pytest\n\nfrom zoo_keeper.core import genome, kit\n\n\ndef test_pew_is_discovered_and_validates():\n    assert "pew" in genome.list_species()\n    assert genome.validate_genome(genome.load_species("pew")) == []\n\n\ndef _plan(dims=(3.6, 0.62, 0.95)):\n    return kit.plan_kit({"building_id": "t", "slots": [{\n        "slot_id": "pew_0", "role": "prop", "size_mod": "full", "style": 1,\n        "species": "pew",\n        "fit": {"dims": list(dims), "pivot": "center"}}]},\n        theme="delco", style=1)\n\n\ndef test_pew_plans_at_its_authored_dims():\n    plan = _plan()\n    assert plan["species_fallbacks"] == []\n    assert plan["modules"][0]["species"] == "pew"\n\n\ndef test_a_pew_is_one_stained_wood():\n    """One material, so a row of pews is one mesh to the merge: every style plans wood, in an oak\'s brown."""\n    g = genome.load_species("pew")\n    for name, s in g["styles"].items():\n        r, gr, b = s["color"]\n        assert s["material"] == "wood" and r > gr > b, name\n\n\ndef test_bpy_a_pew_is_its_slot_with_a_seat_a_back_and_a_rack(tmp_path):\n    pytest.importorskip("bpy")\n    import bpy\n    from mathutils import Vector\n    from zoo_keeper.bpylayer import build as B\n    for o in list(bpy.data.objects):\n        bpy.data.objects.remove(o, do_unlink=True)\n    w, d, h = 3.6, 0.62, 0.95\n    m = _plan((w, d, h))["modules"][0]\n    B.build_module(m, str(tmp_path / m["stem"]), theme="delco", style=1, options={"save_blend": False})\n    meshes = [o for o in bpy.data.objects if o.type == "MESH" and not o.name.endswith("-colonly")]\n    names = sorted(o.name.split(".")[0] for o in meshes)\n    assert names == sorted(["Pew_End_L", "Pew_End_R", "Pew_Seat", "Pew_Back", "Pew_TopRail", "Pew_Rack"]), names\n    pts = [o.matrix_world @ Vector(c) for o in meshes for c in o.bound_box]\n    for axis, size in ((0, w), (1, d), (2, h)):\n        lo, hi = min(p[axis] for p in pts), max(p[axis] for p in pts)\n        assert hi - lo == pytest.approx(size, abs=1e-3), (axis, lo, hi)\n    assert len({s.material.name for o in meshes for s in o.material_slots}) == 1\n\n    def box(name):\n        o = next(o for o in meshes if o.name.startswith(name))\n        q = [o.matrix_world @ Vector(c) for c in o.bound_box]\n        return [min(p[i] for p in q) for i in range(3)], [max(p[i] for p in q) for i in range(3)]\n    (slo, shi), (blo, bhi), (rlo, rhi) = box("Pew_Seat"), box("Pew_Back"), box("Pew_Rack")\n    assert shi[2] == pytest.approx(-h / 2.0 + 0.45, abs=0.01)          # a seat 0.45 m up\n    assert slo[1] == pytest.approx(-d / 2.0, abs=0.01) and blo[1] < shi[1] <= bhi[1]   # sat on from the front, into the back\n    assert bhi[2] > shi[2] + 0.35                                    # a back to lean on\n    assert blo[1] <= rlo[1] < bhi[1] < rhi[1] <= d / 2.0                 # the rack behind, for the next row\n    assert shi[1] - slo[1] < 0.5                                             # a seat a pew\'s depth\n\n\ndef test_bpy_a_deep_slot_keeps_the_seat_and_gains_a_kneeler(tmp_path):\n    """The funeral home\'s authored `pew_row` boxes are 0.9 m deep: the seat stays a seat, the rest is a kneeler."""\n    pytest.importorskip("bpy")\n    import bpy\n    from mathutils import Vector\n    from zoo_keeper.bpylayer import build as B\n    for o in list(bpy.data.objects):\n        bpy.data.objects.remove(o, do_unlink=True)\n    w, d, h = 8.0, 0.9, 0.9\n    m = _plan((w, d, h))["modules"][0]\n    assert m["species"] == "pew"\n    B.build_module(m, str(tmp_path / m["stem"]), theme="delco", style=1, options={"save_blend": False})\n    meshes = {o.name.split(".")[0]: o for o in bpy.data.objects if o.type == "MESH" and not o.name.endswith("-colonly")}\n    assert "Pew_Kneeler" in meshes, sorted(meshes)\n    q = [meshes["Pew_Seat"].matrix_world @ Vector(c) for c in meshes["Pew_Seat"].bound_box]\n    assert max(p[1] for p in q) - min(p[1] for p in q) < 0.5\n    k = [meshes["Pew_Kneeler"].matrix_world @ Vector(c) for c in meshes["Pew_Kneeler"].bound_box]\n    assert max(p[2] for p in k) < -h / 2.0 + 0.25 and max(p[1] for p in k) > d / 2.0 - 0.01\n'}
CHANGELOG = "## [1.130.0] - `pew`: a seat for a row that faces one front\n\n**The factory's roadmap 308**: a chapel, a funeral home's viewing rooms, two courtrooms and two assembly halls were\nfurnished as a cafeteria, partly because there was nothing to stand in rows facing a front. `bench` is a street bench\nwith no back.\n\n### Added\n- **`pew`**, minted by `tools/new_species.py` and shaped. Reference: an American oak pew, the common catalogue\n  pattern. It has:\n  - two end panels the pew's full height and depth;\n  - a seat 0.45 m up, 0.46 m deep, meeting the back;\n  - a back with a top rail, and a hymnal rack on the back's rear for the row behind;\n  - in a slot deep enough, a kneeler for that row at the floor.\n\n  One stained-oak wood in every style: one material, one mesh a pew to the merge. The genome runs 1.2-8.0 m long,\n  0.5-1.0 m deep and 0.85-1.1 m tall, so it reaches the 8.0 x 0.9 m `pew_row` boxes Deli Counter's funeral home\n  authored. Its budget is 360 tris; the census measured 308 / 308 / 352.\n- **No coincident faces**: every part runs 1 cm into whatever it meets and stops 5 mm short of the ends' outer\n  faces. The back and the rack's lip end half as deep in the ends as the other parts. The census's first reading\n  was 4 pairs a corner, the back's end faces sharing planes with the seat's and the rack's, and now reads 0 at all\n  three corners. The coincident-face census grows by three builds, to 420.\n- **The seat is a pew's depth, whatever the slot's.** A deep slot keeps the seat and gains the kneeler. A first\n  draft ran the seat back to a back pushed against the slot's rear.\n\n### Tests\n- `tests/test_pew.py`:\n  - discovered, validates, plans at its dims, one stained wood;\n  - built in Blender: its slot's extents, its six parts, one material, the seat 0.45 m up, the rack behind the back;\n  - a 0.9 m slot keeps a pew's seat and gains a kneeler.\n\n  Fails on 1.129.0, which has no pew.\n\n"
OLD_VERSION, NEW_VERSION = '1.129.0', '1.130.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: zoo/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: zoo/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: zoo/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: zoo/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Zoo %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in zoo/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
